    pub fn k_items_with_maximum_sum(num_ones: i32, num_zeros: i32, num_neg_ones: i32, k: i32) -> i32 {
        let num_ones = num_ones as i64;
        let num_zeros = num_zeros as i64;
        let num_neg_ones = num_neg_ones as i64;
        let k = k as i64;

        if k <= num_ones {
            k as i32
        } else if k <= num_ones + num_zeros {
            num_ones as i32
        } else {
            (num_ones - (k - num_ones - num_zeros)) as i32
        }
    }
}

